function SectionTitle({ children, info, subtitle, inlineSubtitle = false }) {
    const titleText = String(children ?? "");

    const defaultSubtitles = {
        "Receivables Aging Summary": "Outstanding receivables grouped by aging bucket",
        "Receivables Trend": "Historical movement of total receivables and DSO",
        "Receivables by Parent Division": "Receivable exposure across parent divisions",
        "Top 10 Customers by Receivables": "Customers contributing the highest receivable balances",
        "Overdue Summary": "Distribution of overdue receivable exposure",
        "Receivables by Sub-Division": "Receivable exposure across sub-divisions",
        "Month-on-Month Receivables": "Monthly receivable balance movement",
    };

    const matchedSubtitle = Object.entries(defaultSubtitles).find(([key]) =>
        titleText.startsWith(key)
    )?.[1];

    return (
        <div style={{ marginBottom: 10, minWidth: 0 }}>
            <div
                style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 2,
                    fontSize: "0.88rem",
                    fontWeight: 800,
                    color: "#0f172a",
                    lineHeight: 1.2,
                    minWidth: 0,
                }}
            >
                {children}
                {info && <InfoIcon title={info} />}
                {inlineSubtitle && (subtitle || matchedSubtitle) && (
                    <span
                        style={{
                            marginLeft: 6,
                            fontSize: "0.68rem",
                            fontWeight: 500,
                            color: "#64748b",
                            lineHeight: 1.35,
                            whiteSpace: "nowrap",
                            overflow: "hidden",
                            textOverflow: "ellipsis",
                            minWidth: 0,
                        }}
                    >
                        {subtitle || matchedSubtitle}
                    </span>
                )}
            </div>
            {!inlineSubtitle && (subtitle || matchedSubtitle) && (
                <div
                    style={{
                        marginTop: 3,
                        fontSize: "0.68rem",
                        fontWeight: 500,
                        color: "#64748b",
                        lineHeight: 1.35,
                    }}
                >
                    {subtitle || matchedSubtitle}
                </div>
            )}
        </div>
    );
}



function SectionActions({
    onViewAll,
    onExportExcel,
    onExportPdf,
    rightContent = null,
}) {
    const [open, setOpen] = useState(false);
    const menuRef = useRef(null);

    useEffect(() => {
        const handleOutside = (event) => {
            if (menuRef.current && !menuRef.current.contains(event.target)) {
                setOpen(false);
            }
        };

        document.addEventListener("mousedown", handleOutside);
        return () => document.removeEventListener("mousedown", handleOutside);
    }, []);

    const runAction = (callback) => {
        setOpen(false);
        if (typeof callback === "function") callback();
    };

    const itemStyle = {
        width: "100%",
        height: 34,
        border: "none",
        background: "transparent",
        borderRadius: 6,
        display: "flex",
        alignItems: "center",
        gap: 9,
        padding: "0 10px",
        color: "#334155",
        fontSize: 12,
        fontWeight: 800,
        cursor: "pointer",
        textAlign: "left",
    };

    return (
        <div
            ref={menuRef}
            style={{
                position: "absolute",
                top: 9,
                right: 9,
                zIndex: 50,
                display: "flex",
                alignItems: "center",
                gap: 7,
            }}
        >
            {rightContent}

            <button
                type="button"
                onClick={() => setOpen((value) => !value)}
                aria-label="More options"
                style={{
                    width: 28,
                    height: 28,
                    border: "none",
                    background: "transparent",
                    color: "#64748b",
                    borderRadius: 6,
                    fontSize: 20,
                    lineHeight: 1,
                    cursor: "pointer",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    padding: 0,
                }}
            >
                ⋮
            </button>

            {open && (
                <div
                    style={{
                        position: "absolute",
                        top: 31,
                        right: 0,
                        width: 165,
                        padding: 5,
                        background: "#ffffff",
                        border: "1px solid #e2e8f0",
                        borderRadius: 9,
                        boxShadow: "0 8px 24px rgba(15, 23, 42, 0.14)",
                        zIndex: 9999,
                    }}
                >
                    <button
                        type="button"
                        onClick={() => runAction(onViewAll)}
                        style={itemStyle}
                        onMouseEnter={(e) => { e.currentTarget.style.background = "#f1f5ff"; }}
                        onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; }}
                    >

                        <span>🔎 View All</span>
                    </button>

                    {typeof onExportExcel === "function" && (
                        <button
                            type="button"
                            onClick={() => runAction(onExportExcel)}
                            style={itemStyle}
                            onMouseEnter={(e) => { e.currentTarget.style.background = "#f1f5ff"; }}
                            onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; }}
                        >
                            <span>📊 Export Excel</span>
                        </button>
                    )}

                    {typeof onExportPdf === "function" && (
                        <button
                            type="button"
                            onClick={() => runAction(onExportPdf)}
                            style={itemStyle}
                            onMouseEnter={(e) => { e.currentTarget.style.background = "#f1f5ff"; }}
                            onMouseLeave={(e) => { e.currentTarget.style.background = "transparent"; }}
                        >
                            <span>📄 Export PDF</span>
                        </button>
                    )}
                </div>
            )}
        </div>
    );
}

function FilterSelect({
    label,
    value,
    options = [],
    onChange,
    multiple = false,
    flex = "0 1 100px",
    includeAllOption = false,
}) {
    const [open, setOpen] = useState(false);
    const [search, setSearch] = useState("");
    const dropdownRef = useRef(null);

    /* ----------------------------------------------------------
       NORMALIZE SELECTED VALUES
    ---------------------------------------------------------- */
    const selectedValues = multiple
        ? Array.isArray(value)
            ? value
            : value !== undefined && value !== null && value !== ""
                ? [value]
                : []
        : [];

    /* ----------------------------------------------------------
       CLOSE WHEN CLICKING OUTSIDE
    ---------------------------------------------------------- */
    useEffect(() => {
        const handleOutsideClick = (event) => {
            if (
                dropdownRef.current &&
                !dropdownRef.current.contains(event.target)
            ) {
                setOpen(false);
                setSearch("");
            }
        };

        document.addEventListener("mousedown", handleOutsideClick);

        return () => {
            document.removeEventListener("mousedown", handleOutsideClick);
        };
    }, []);

    /* ----------------------------------------------------------
       NORMALIZE OPTIONS
       KEEP "All" INSIDE DROPDOWN
    ---------------------------------------------------------- */
    const normalizedOptions = Array.from(
        new Set(
            (options || [])
                .filter(
                    (option) =>
                        option !== null &&
                        option !== undefined &&
                        String(option).trim() !== ""
                )
                .map((option) => String(option))
        )
    );

    /*
       Always keep "All" as the first dropdown option.
       If backend options already contain All, remove duplicate.
    */
    const finalOptions = includeAllOption
        ? ["All", ...normalizedOptions.filter((option) => option.toLowerCase() !== "all")]
        : normalizedOptions.filter((option) => option !== "All");

    /* ----------------------------------------------------------
       SEARCH
    ---------------------------------------------------------- */
    const filteredOptions = finalOptions.filter((option) =>
        option.toLowerCase().includes(search.toLowerCase())
    );

    /* ----------------------------------------------------------
       SELECT ALL
    ---------------------------------------------------------- */
    const handleSelectAll = () => {
        if (!multiple) return;

        onChange(
            finalOptions.filter((option) => option !== "All")
        );
    };

    /* ----------------------------------------------------------
       CLEAR
    ---------------------------------------------------------- */
    const handleClear = () => {
        if (!multiple) {
            onChange("");
        } else {
            onChange([]);
        }
    };

    /* ----------------------------------------------------------
       INDIVIDUAL OPTION
    ---------------------------------------------------------- */
    const handleOptionClick = (option) => {
        /* SINGLE SELECT */
        if (!multiple) {
            if (option === "All") {
                onChange("");
            } else {
                onChange(option);
            }

            setOpen(false);
            setSearch("");
            return;
        }

        /* MULTI SELECT */
        if (option === "All") {
            onChange([]);
            return;
        }

        let nextValues = selectedValues.filter(
            (item) => String(item) !== "All"
        );

        if (nextValues.includes(option)) {
            nextValues = nextValues.filter(
                (item) => item !== option
            );
        } else {
            nextValues = [...nextValues, option];
        }

        onChange(nextValues);
    };

    /* ----------------------------------------------------------
       DISPLAY VALUE
       DEFAULT = ALL
    ---------------------------------------------------------- */
    const getDisplayValue = () => {
        if (!multiple) {
            return value !== undefined && value !== null && String(value) !== "" && String(value).trim().toUpperCase() !== "ALL"
                ? String(value)
                : "All";
        }

        if (selectedValues.length === 0) {
            return "All";
        }

        if (selectedValues.length === 1) {
            return String(selectedValues[0]);
        }

        return `${selectedValues.length} selected`;
    };

    /* ----------------------------------------------------------
       ALL SELECTED
    ---------------------------------------------------------- */
    const selectableOptions = finalOptions.filter(
        (option) => option !== "All"
    );

    const allSelected =
        multiple &&
        selectableOptions.length > 0 &&
        selectableOptions.every((item) =>
            selectedValues.includes(item)
        );

    return (
        <div
            ref={dropdownRef}
            style={{
                flex,
                minWidth: 0,
                position: "relative",
            }}
        >
            {/* =====================================================
                LABEL
            ===================================================== */}
            <label
                style={{
                    display: "block",
                    fontSize: 10.5,
                    fontWeight: 700,
                    color: "#334155",
                    marginBottom: 4,
                    lineHeight: "12px",
                    whiteSpace: "nowrap",
                }}
            >
                {label}
            </label>

            {/* =====================================================
                FIELD
            ===================================================== */}
            <button
                type="button"
                onClick={() => {
                    setOpen((prev) => !prev);

                    if (open) {
                        setSearch("");
                    }
                }}
                style={{
                    width: "100%",
                    height: 32,
                    boxSizing: "border-box",
                    border: open
                        ? "1px solid #5b5bea"
                        : "1px solid #dce3ee",
                    borderRadius: 7,
                    padding: "0 25px 0 9px",
                    background: "#ffffff",
                    color: "#243b63",
                    fontSize: 11.5,
                    fontWeight: 500,
                    outline: "none",
                    cursor: "pointer",
                    textAlign: "left",
                    position: "relative",
                    overflow: "hidden",
                    whiteSpace: "nowrap",
                    textOverflow: "ellipsis",
                }}
            >
                {getDisplayValue()}

                <span
                    style={{
                        position: "absolute",
                        right: 10,
                        top: "50%",
                        transform: `translateY(-50%) ${open
                            ? "rotate(180deg)"
                            : "rotate(0deg)"
                            }`,
                        fontSize: 9,
                        color: "#52638a",
                        transition: "transform 0.15s ease",
                        pointerEvents: "none",
                    }}
                >
                    ▼
                </span>
            </button>

            {/* =====================================================
                DROPDOWN
            ===================================================== */}
            {open && (
                <div
                    style={{
                        position: "absolute",
                        top: "calc(100% + 5px)",
                        left: 0,
                        width: "max-content",
                        minWidth: 220,
                        maxWidth: "min(420px, 80vw)",
                        background: "#ffffff",
                        border: "1px solid #dce3ee",
                        borderRadius: 9,
                        boxShadow:
                            "0 8px 24px rgba(24, 45, 80, 0.14)",
                        zIndex: 9999,
                        overflow: "visible",
                    }}
                >
                    {/* =================================================
                        SEARCH
                    ================================================= */}
                    <div
                        style={{
                            padding: "8px 8px 6px",
                            borderBottom: "1px solid #edf1f7",
                        }}
                    >
                        <div
                            style={{
                                position: "relative",
                            }}
                        >
                            <input
                                type="text"
                                value={search}
                                onChange={(e) =>
                                    setSearch(e.target.value)
                                }
                                onClick={(e) =>
                                    e.stopPropagation()
                                }
                                placeholder={`Search ${label}`}
                                autoFocus
                                style={{
                                    width: "100%",
                                    height: 30,
                                    boxSizing: "border-box",
                                    border: "1px solid #dce3ee",
                                    borderRadius: 7,
                                    padding: "0 9px 0 28px",
                                    background: "#f8fafc",
                                    color: "#24366b",
                                    fontSize: 10.5,
                                    outline: "none",
                                }}
                            />

                            <span
                                style={{
                                    position: "absolute",
                                    left: 9,
                                    top: "50%",
                                    transform:
                                        "translateY(-50%)",
                                    color: "#64748b",
                                    fontSize: 12,
                                    pointerEvents: "none",
                                }}
                            >
                                🔍
                            </span>
                        </div>
                    </div>

                    {/* =================================================
                        SELECT ALL / CLEAR
                    ================================================= */}
                    {multiple && (
                        <div
                            style={{
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "space-between",
                                padding: "7px 9px",
                                borderBottom:
                                    "1px solid #edf1f7",
                                background: "#fafbfe",
                            }}
                        >
                            <button
                                type="button"
                                onClick={handleSelectAll}
                                style={{
                                    border: "none",
                                    background: "transparent",
                                    padding: 0,
                                    color: "#4f46e5",
                                    fontSize: 10,
                                    fontWeight: 700,
                                    cursor: "pointer",
                                }}
                            >
                                {allSelected
                                    ? "Unselect All"
                                    : "Select All"}
                            </button>

                            <button
                                type="button"
                                onClick={handleClear}
                                style={{
                                    border: "none",
                                    background: "transparent",
                                    padding: 0,
                                    color: "#64748b",
                                    fontSize: 10,
                                    fontWeight: 600,
                                    cursor: "pointer",
                                }}
                            >
                                Clear
                            </button>
                        </div>
                    )}

                    {/* =================================================
                        OPTIONS
                    ================================================= */}
                    <div
                        style={{
                            maxHeight: 320,
                            overflowY: "auto",
                            overflowX: "visible",
                            padding: "4px 0",
                        }}
                    >
                        {filteredOptions.length === 0 ? (
                            <div
                                style={{
                                    padding: "14px 10px",
                                    textAlign: "center",
                                    color: "#94a3b8",
                                    fontSize: 10.5,
                                }}
                            >
                                No options found
                            </div>
                        ) : (
                            filteredOptions.map((option) => {
                                const selected = multiple
                                    ? option === "All"
                                        ? selectedValues.length === 0
                                        : selectedValues.includes(option)
                                    : option === "All"
                                        ? (!value || String(value).trim().toUpperCase() === "ALL")
                                        : String(value || "") === option;

                                return (
                                    <button
                                        key={option}
                                        type="button"
                                        onClick={() =>
                                            handleOptionClick(option)
                                        }
                                        style={{
                                            width: "100%",
                                            minHeight: 31,
                                            display: "flex",
                                            alignItems: "center",
                                            gap: 8,
                                            padding: "5px 10px",
                                            border: "none",
                                            background: selected
                                                ? "#eef2ff"
                                                : "#ffffff",
                                            color: selected
                                                ? "#243b8f"
                                                : "#334155",
                                            fontSize: 10.5,
                                            fontWeight: selected
                                                ? 700
                                                : 500,
                                            cursor: "pointer",
                                            textAlign: "left",
                                            whiteSpace: "normal",
                                            overflowWrap: "anywhere",
                                        }}
                                    >
                                        {multiple && (
                                            <span
                                                style={{
                                                    width: 14,
                                                    height: 14,
                                                    minWidth: 14,
                                                    borderRadius: 3,
                                                    border: selected
                                                        ? "1px solid #5b5bea"
                                                        : "1px solid #cbd5e1",
                                                    background: selected
                                                        ? "#5b5bea"
                                                        : "#ffffff",
                                                    display: "flex",
                                                    alignItems: "center",
                                                    justifyContent:
                                                        "center",
                                                    color: "#ffffff",
                                                    fontSize: 9,
                                                    fontWeight: 800,
                                                    boxSizing:
                                                        "border-box",
                                                }}
                                            >
                                                {selected ? "✓" : ""}
                                            </span>
                                        )}

                                        <span
                                            style={{
                                                overflow: "visible",
                                                textOverflow: "clip",
                                                whiteSpace: "normal",
                                                overflowWrap: "anywhere",
                                                flex: 1,
                                                minWidth: 0,
                                            }}
                                        >
                                            {option}
                                        </span>
                                    </button>
                                );
                            })
                        )}
                    </div>
                </div>
            )}
        </div>
    );
}


/* ================================================================
   DATE FILTER
   Initial display = All
   All remains available inside dropdown
   ================================================================ */
function DateFilter({
    value,
    onChange,
}) {
    const dateInputRef = useRef(null);

    const openCalendar = () => {
        if (dateInputRef.current) {
            if (
                typeof dateInputRef.current.showPicker === "function"
            ) {
                dateInputRef.current.showPicker();
            } else {
                dateInputRef.current.click();
            }
        }
    };

    const handleDateChange = (event) => {
        const selectedDate = event.target.value;

        if (!selectedDate) return;

        // Immediately send YYYY-MM-DD to parent
        onChange(selectedDate);
    };

    return (
        <div
            style={{
                flex: "0.92 1 0",
                minWidth: 0,
                position: "relative",
            }}
        >
            <label
                style={{
                    display: "block",
                    fontSize: 10.5,
                    fontWeight: 700,
                    color: "#334155",
                    marginBottom: 4,
                    lineHeight: "12px",
                    whiteSpace: "nowrap",
                }}
            >
                As On Date
            </label>

            {/* Hidden native calendar */}
            <input
                ref={dateInputRef}
                type="date"
                value={value || ""}
                onChange={handleDateChange}
                style={{
                    position: "absolute",
                    width: 1,
                    height: 1,
                    opacity: 0,
                    pointerEvents: "none",
                }}
            />

            {/* Visible field */}
            <button
                type="button"
                onClick={openCalendar}
                style={{
                    width: "100%",
                    height: 34,
                    boxSizing: "border-box",
                    border: "1px solid #dce3ee",
                    borderRadius: 9,
                    padding: "0 38px 0 11px",
                    background: "#f4f7fb",
                    color: "#24366b",
                    fontSize: 11,
                    fontWeight: 600,
                    outline: "none",
                    cursor: "pointer",
                    textAlign: "left",
                    position: "relative",
                }}
            >
                {value
                    ? String(value).split("-").reverse().join("-")
                    : "Select Date"}

                <span
                    style={{
                        position: "absolute",
                        right: 10,
                        top: "50%",
                        transform: "translateY(-50%)",
                        fontSize: 15,
                        pointerEvents: "none",
                    }}
                >
                    📅
                </span>
            </button>
        </div>
    );
}
