                    height: isViewAllMaximized ? "100dvh" : "92vh",
                    maxWidth: isViewAllMaximized ? "100vw" : "1540px",
                    maxHeight: isViewAllMaximized ? "100dvh" : "92vh",
                    background:
                        "#f7faff",
                    borderRadius: isViewAllMaximized ? 0 : 10,
                    overflow:
                        "hidden",
                    boxShadow:
                        "0 18px 55px rgba(15, 23, 42, 0.28)",
